class Solution {
public:
    int countDominantElements(vector<int>& nums) {
        int n = nums.size();
        int count = 0;
        for (int i = 0; i < n; i++) {
            long long sum = 0;
            int k = 0;
            if (i > 0) { sum += nums[i - 1]; k++; }
            if (i < n - 1) { sum += nums[i + 1]; k++; }
            if (k == 0 || (long long)nums[i] * k >= sum) {
                count++;
            }
        }
        return count;
    }
};
